for number,title,s,es,ids in [
(81,'Machine reply residual colour is unchecked','validate_machine_reply_fields accepts RESIDUAL_COLOUR=Exact without any dual witness and accepts an arbitrary colour string. The field can be required yet only presence is checked; the declared enum/dual-witness refusal constants do not enforce this boundary. Claimed-result evaluation still retains a separate claim-evaluator obstruction, so this is not a proven semantic promotion.',[ev('llm_turn_run_root.py',(653,665),(692,772),(1257,1258))],[102]),
(82,'Host-status block can omit expected candidate and root','With host_status phase and explicit expected candidate/run-root IDs, ABSENT values pass. Comparisons run only when the value is already present and non-ABSENT, so expected identity is not a presence requirement. Proposal-phase ABSENT is separately intentional.',[ev('llm_turn_run_root.py',(739,763))],[103]),
(83,'Turn content task_id property references a nonexistent field','A normally bound LlmTurnContentArtifactV1 raisesAttributeError on task_id because fallback reads task_packet_id while its field is packet_id. Explicit_task_id bypasses fallback but is unvalidated/unbound to content identity.',[ev('llm_turn_run_root.py',(215,228),(247,255))],[104]),
(84,'Prompt direct ID override and nested mutability weaken object contract','Direct PromptArtifact accepts arbitrary explicit_artifact_id and returns it instead of computed content address. Strict from_dict correctly rejects the resulting mismatch. The frozen constructor also accepts an open_obstructions list which can mutate after validation and accepts negative hint magnitude. Dynamic digest changes with list mutation; no stale-hash claim is made.',[ev('prompt_artifact.py',(107,114),(376,394),(442,452),(500,504),(628,631))],[105,106])]:n['findings'].append({'id':'PFPDOMAIN-F'+str(number).zfill(3),'title':title,'statement':s,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':['PFPDOMAIN-C'+str(i).zfill(3) for i in ids],'status':'confirmed_bounded_source_and_probe','limits':'Actual read-vetted Python modules imported through hash guard; all34 transitive domain imports bound to full-read hashes. No provider/foreign/native import, model calls or downstream promotion.'})
